-- Moves classifier reference data (client types, asset types, condition states, activity types,
-- project stages, priorities, treatment methods) from internal/seed/classifiers.go into a
-- migration, so it lives in source-controlled SQL like the rest of the schema instead of being
-- applied by app code on every boot. INSERT OR IGNORE mirrors the seed code's own idempotency
-- (Classifier(type, code) is UNIQUE — see 0001_init.sql), so this is safe to run against a
-- database already seeded by the old Go path before this migration existed.
INSERT OR IGNORE INTO Classifier (id, type, code, sequence, title, description, data, updatedAt) VALUES ('clsfr_client_type_individual', 'client_type', 'individual', 0, 'Individual', 'A private collector or individual owner.', NULL, strftime('%Y-%m-%d %H:%M:%f', 'now'));
